using System.Globalization;
using System.Text.RegularExpressions;

public static class Template
{
    private static readonly Regex Placeholder = new(@"\{\{\{\{|\{\{\s*(?<name>\w+)\s*(?:\|\s*(?<filter>\w+)\s*)?\}\}", RegexOptions.Compiled);

    public static string Fill(string template, IReadOnlyDictionary<string, object?> values) =>
        Placeholder.Replace(template, m =>
        {
            if (m.Value == "{{{{") return "{{";
            string name = m.Groups["name"].Value;
            if (!values.TryGetValue(name, out object? value)) throw new KeyNotFoundException($"no value for {name}");
            string filter = m.Groups["filter"].Value;
            return filter switch
            {
                "" => Convert.ToString(value, CultureInfo.InvariantCulture) ?? "",
                "upper" => (Convert.ToString(value, CultureInfo.InvariantCulture) ?? "").ToUpperInvariant(),
                "lower" => (Convert.ToString(value, CultureInfo.InvariantCulture) ?? "").ToLowerInvariant(),
                "money" => Convert.ToDecimal(value, CultureInfo.InvariantCulture).ToString("0.00", CultureInfo.InvariantCulture),
                _ => throw new FormatException($"unknown filter {filter}"),
            };
        });
}

unitTests:
var v = new Dictionary<string, object?> { ["name"] = "Ada", ["amount"] = 12.5, ["city"] = "LONDON", ["note"] = null };

Test("plain and filtered", () =>
{
    CheckEq(Template.Fill("Hi {{ name|upper }}, you owe {{amount|money}}.", v), "Hi ADA, you owe 12.50.");
    CheckEq(Template.Fill("{{name}} in {{ city | lower }}", v), "Ada in london");
    CheckEq(Template.Fill("[{{note}}]", v), "[]");
    CheckEq(Template.Fill("{{{{name}}", v), "{{name}}");
});

Test("errors", () =>
{
    CheckThrows<KeyNotFoundException>(() => Template.Fill("{{missing}}", v));
    CheckThrows<FormatException>(() => Template.Fill("{{name|shout}}", v));
});

